import React, { useEffect, useState } from "react";
import api from "../services/api";

const BookingForm = ({
  formData,
  onChange,
  onSubmit,
  onAvailabilityCheck,
  loading
}) => {
  const [blockId, setBlockId] = useState("");
  const [blocks, setBlocks] = useState([]);
  const [resources, setResources] = useState([]);
  const [blocksLoading, setBlocksLoading] = useState(false);
  const [resourceLoading, setResourceLoading] = useState(false);

  // sync blockId with formData
  useEffect(() => {
    setBlockId(formData.blockId || "");
  }, [formData.blockId]);

  // fetch blocks
  useEffect(() => {
    const fetchBlocks = async () => {
      setBlocksLoading(true);
      try {
        const res = await api.get("/blocks");
        console.log("Blocks:", res.data);
        setBlocks(res.data || []);
      } catch (err) {
        console.log("Blocks error:", err);
        setBlocks([]);
      } finally {
        setBlocksLoading(false);
      }
    };

    fetchBlocks();
  }, []);

  // ✅ fetch resources when block changes
  useEffect(() => {
    const fetchResources = async () => {
      if (!blockId) {
        setResources([]);
        return;
      }

      setResourceLoading(true);

      try {
        console.log("Fetching resources for block:", blockId);

        const res = await api.get(`/blocks/${blockId}/resources`);

        console.log("Resources:", res.data);

        setResources(res.data || []);
      } catch (err) {
        console.log("Resource error:", err);
        setResources([]);
      } finally {
        setResourceLoading(false);
      }
    };

    fetchResources();
  }, [blockId]);

  const handleBlockChange = (e) => {
    const value = e.target.value;

    setBlockId(value);

    // reset resource when block changes
    onChange({
      target: {
        name: "blockId",
        value
      }
    });

    onChange({
      target: {
        name: "resourceId",
        value: ""
      }
    });
  };

  return (
    <div className="panel-card">
      <div className="panel-header">
        <div>
          <h3>Create Booking</h3>
          <p>Choose a block, resource, date, and time slot.</p>
        </div>
      </div>

      <form className="grid-form" onSubmit={onSubmit}>

        {/* BLOCK */}
        <label>
          <span>Block</span>
          <select value={blockId} onChange={handleBlockChange} required>
            <option value="">
              {blocksLoading ? "Loading blocks..." : "Select block"}
            </option>

            {blocks.map((b) => (
              <option key={b.id} value={b.id}>
                Block {b.name}
              </option>
            ))}
          </select>
        </label>

        {/* RESOURCE */}
        <label>
          <span>Resource</span>
          <select
            name="resourceId"
            value={formData.resourceId || ""}
            onChange={onChange}
            required
            disabled={!blockId}
          >
            <option value="">
              {!blockId
                ? "Select block first"
                : resourceLoading
                ? "Loading..."
                : resources.length === 0
                ? "No resources found"
                : "Select resource"}
            </option>

            {resources.map((r) => (
              <option key={r.id} value={r.id}>
                {r.name}
              </option>
            ))}
          </select>
        </label>

        {/* DATE */}
        <label>
          <span>Date</span>
          <input
            type="date"
            name="bookingDate"
            value={formData.bookingDate || ""}
            onChange={onChange}
            required
          />
        </label>

        {/* START TIME */}
        <label>
          <span>Start time</span>
          <input
            type="time"
            name="startTime"
            value={formData.startTime || ""}
            onChange={onChange}
            required
          />
        </label>

        {/* END TIME */}
        <label>
          <span>End time</span>
          <input
            type="time"
            name="endTime"
            value={formData.endTime || ""}
            onChange={onChange}
            required
          />
        </label>

        {/* PURPOSE */}
        <label className="full-width">
          <span>Purpose</span>
          <textarea
            name="purpose"
            value={formData.purpose || ""}
            onChange={onChange}
            rows="4"
            placeholder="Add purpose for this booking"
          />
        </label>

        <div className="form-actions full-width">
          <button type="button" onClick={onAvailabilityCheck}>
            Check Availability
          </button>

          <button type="submit" disabled={loading}>
            {loading ? "Submitting..." : "Create Booking"}
          </button>
        </div>
      </form>
    </div>
  );
};

export default BookingForm;
